'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process');
const root=path.resolve(__dirname,'../..'),assets=process.env.KRASNOV_DESCRIPTIONS_ASSET_DIR||root,read=f=>fs.readFileSync(path.join(assets,f),'utf8'),base='431d69e',languages=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
const sources=JSON.parse(fs.readFileSync(path.join(root,'outils/audits/I18N-KRASNOV-DESCRIPTIONS-871-sources.json'),'utf8'));
const original=f=>execFileSync('git',['show',base+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6});
const rows=s=>[...s.matchAll(/^\s*\[("[^\n]+")\],?$/gm)].map(m=>JSON.parse('['+m[1]+']'));
function api(source,language='fr',country='soviet',enabled=true){const c={state:{country},RP_I18N_GAME_ENABLED:enabled,RPPlateauI18n:{language:()=>language}};c.window=c;vm.createContext(c);vm.runInContext(source,c);return c.RPSovarkaDescI18n;}
test('Krasnov : dix ajouts, neuf langues, français exact et toutes les anciennes traductions conservées',()=>{
 const before=rows(original('i18n/sovarka-descriptions-resources.js')),after=rows(read('i18n/sovarka-descriptions-resources.js'));
 // Lots suivants permis à la suite (15/11 : quatre descriptions de Krasnov par Claude) : ces dix lignes restent en place.
 assert.ok(after.length>=before.length+10);assert.deepEqual(after.slice(0,before.length),before);
 assert.deepEqual(after.slice(before.length,before.length+10).map(r=>r[0]),sources);assert.equal(new Set(after.map(r=>r[0])).size,after.length);
 for(const row of after.slice(before.length,before.length+10)){assert.equal(row.length,9);for(const [i,lang]of languages.entries()){assert.ok(row[i].trim());if(i)assert.notEqual(row[i],row[0]);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),lang).desc(row[0]),row[i]);}assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'ar','republic').desc(row[0]),row[0]);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'de','soviet',false).desc(row[0]),row[0]);}
 const missing=read('i18n/sovarka-descriptions-resources.js').replace(JSON.stringify(after[before.length][8]),'""');assert.notEqual(missing,read('i18n/sovarka-descriptions-resources.js'));assert.equal(api(missing,'de').desc(sources[0]),sources[0]);
 assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'inconnue').desc(sources[0]),sources[0]);
 assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'de').desc('Texte joueur <intact>'), 'Texte joueur <intact>');
 const withoutRows=s=>s.replace(/const L=\[[\s\S]*?\n \];/,'const L=[];');assert.equal(withoutRows(read('i18n/sovarka-descriptions-resources.js')),withoutRows(original('i18n/sovarka-descriptions-resources.js')));
});
test('Krasnov : fichiers métier identiques à main, modifications UI limitées au cache et au sens de lecture',()=>{
 const proof=JSON.parse(fs.readFileSync(path.join(root,'outils/audits/I18N-KRASNOV-DESCRIPTIONS-871-preuve.json'))),snapshot=f=>execFileSync('git',['show',proof.codeCommit+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6});
 const changed=execFileSync('git',['diff','--name-only',proof.baseCommit,proof.codeCommit],{cwd:root,encoding:'utf8'}).trim().split('\n');
 const allowed=new Set(['RELAIS.md','plateau.html','i18n/sovarka-descriptions-resources.js','i18n/packed/sovarka-descriptions-resources.js.br','outils/audits/I18N-CATALOGUES-TRANSPORT.json','outils/audits/I18N-NOTIFICATIONS-CORPS-871-production.json','outils/audits/I18N-KRASNOV-DESCRIPTIONS-871-sources.json']);assert.deepEqual(changed.filter(f=>!allowed.has(f)),[]);
 const normalize=s=>s.replace(/sovarka-descriptions-resources\.js\?v=[^"]+/g,'sovarka-descriptions-resources.js?v=VERSION').replace('<div class="piece-desc" id="piece-desc" dir="auto">','<div class="piece-desc" id="piece-desc">');assert.equal(normalize(snapshot('plateau.html')),normalize(original('plateau.html')));
 for(const file of ['data.js','plateau-navigation.js','plateau-core.js','plateau-politique.js','i18n/plateau-init.js','style.css']){assert.equal(snapshot(file),original(file),file);if(proof.integrationCodeCommit)assert.equal(execFileSync('git',['show',proof.integrationCodeCommit+':'+file],{cwd:root,encoding:'utf8',maxBuffer:4e6}),execFileSync('git',['show',proof.integrationMainCommit+':'+file],{cwd:root,encoding:'utf8',maxBuffer:4e6}),file+' après intégration du dernier main');}
});
test('Chromium : 270 bascules, neuf langues, 320/390/1280, RTL et suffixes/saisie/progression conservés sans RPC/PA',async()=>{
 const {chromium}=require('playwright'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:780}}),errors=[],requests=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>{requests.push(r.request().url());return r.abort();});
 const tag=read('plateau.html').match(/<div class="piece-desc" id="piece-desc"[^>]*>/)[0];
 await page.setContent('<!doctype html><html lang="fr"><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body">'+tag+'</div><input id="draft" value="Brouillon <intact>"><div id="scroll" style="height:120px;overflow:auto"><div style="height:1000px">Repère</div></div></body></html>');await page.addStyleTag({content:read('style.css')});
 await page.addScriptTag({content:read('i18n/i18next.min.js')});await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.state={country:'soviet',pa:8,arg:500,inventory:[{id:'intact'}],progression:{stage:3},currentBuilding:'musee',currentRoom:'intact'};window.calls=[];for(const name of ['fetch','sbRpc','doOrder','entrerPiece','deduireCoutOrdre'])window[name]=(...args)=>{calls.push([name,...args]);throw Error('Appel métier interdit');};});
 for(const file of ['i18n/resources.js','i18n/room-resources.js','i18n/sovarka-descriptions-resources.js'])await page.addScriptTag({content:read(file)});
 const navigation=read('plateau-navigation.js'),start=navigation.indexOf('function rpRefreshOpenRoomNames()'),end=navigation.indexOf('\n}',start)+2;assert.ok(start>=0&&end>start);await page.addScriptTag({content:navigation.slice(start,end)+'\nwindow.RPRefreshOpenRoomNames=rpRefreshOpenRoomNames;'});await page.addScriptTag({content:read('i18n/plateau-init.js')});await page.evaluate(()=>document.fonts.ready);
 const suffix=' — Caisse : 1\u202f250 PSK. <contenu joueur intact>';
 for(const fr of sources){await page.evaluate(async({fr,suffix})=>{await i18next.changeLanguage('fr');const node=document.getElementById('piece-desc');node.textContent=fr+suffix;node.setAttribute('data-rp-desc-source',fr);node.setAttribute('data-rp-desc-affichee',fr);document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,6);document.getElementById('scroll').scrollTop=350;},{fr,suffix});const before=await page.evaluate(()=>JSON.stringify({state,calls,value:document.getElementById('draft').value,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,focus:document.activeElement.id,scroll:document.getElementById('scroll').scrollTop})),count=requests.length;
 for(const lang of languages){const got=await page.evaluate(async({lang,fr,suffix})=>{await i18next.changeLanguage(lang);const node=document.getElementById('piece-desc');return{body:node.textContent,expected:RPSovarkaDescI18n.desc(fr)+suffix,source:node.getAttribute('data-rp-desc-source'),dir:getComputedStyle(node).direction,overflow:document.documentElement.scrollWidth>innerWidth,snapshot:JSON.stringify({state,calls,value:document.getElementById('draft').value,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,focus:document.activeElement.id,scroll:document.getElementById('scroll').scrollTop})};},{lang,fr,suffix});assert.equal(got.body,got.expected);if(lang==='fr')assert.equal(got.body,fr+suffix);assert.equal(got.source,fr);assert.equal(got.dir,lang==='ar'?'rtl':'ltr');assert.equal(got.overflow,false,lang+'/'+width);assert.equal(got.snapshot,before);assert.equal(requests.length,count);}}
 assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
